"""The declarative base shared by every model."""

from sqlalchemy import MetaData
from sqlalchemy.orm import DeclarativeBase

# Gives every constraint and index a predictable name (e.g. ck_feedback_rating_value)
# instead of one generated by the database, so error messages are readable and
# future migrations can refer to constraints by name.
NAMING_CONVENTION = {
    "ix": "ix_%(column_0_label)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    """Parent class of every model; holds the shared metadata (the table registry)."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)
